<script lang="ts">import { dropFeature } from '@fex/components-core/upload/features/drop'; import { pasteFeature } from '@fex/components-core/upload/features/paste'; import { previewFeature } from '@fex/components-core/upload/features/preview'; import { uploadFeature } from '@fex/components-core/upload/features/upload'; import { UploadDropzone, UploadRoot, createUpload } from '@fex/components-svelte/primitive/upload'; import { uploadBody, uploadServerUrl } from './api'; import DemoList from './demo-list.svelte'; import DemoSection from './demo-section.svelte'; const upload = createUpload({ multiple: true, features: [dropFeature(), pasteFeature(), previewFeature(), uploadFeature({ request: ({ file, signal, onProgress }) => uploadBody(`${uploadServerUrl}/upload`, file, { fileName: file.name, signal, onProgress }) })] })</script>
<DemoSection title="拖拽、粘贴与图片预览" description="可选行为 feature 共用同一条 addFiles 处理链；支持递归拖入文件夹，也可以聚焦此区域后粘贴剪贴板图片。"><UploadRoot controller={upload}><UploadDropzone>拖入文件或文件夹，或者聚焦此区域后粘贴图片</UploadDropzone><DemoList /></UploadRoot></DemoSection>
